steps.script:
$ErrorActionPreference='Stop'
try {
  $p='C:\TTiTTulares\TTendenciasDedicatedListener.ps1'
  $s=Get-Content -LiteralPath $p -Raw -Encoding UTF8
  $u='C:\TTiTTulares\tt-auto-updater.log'
  $rows=@()
  if(Test-Path -LiteralPath $u){
    $rows=@(Get-Content -LiteralPath $u -Tail 80 | Where-Object {$_ -match 'TTendenciasDedicatedListener.ps1|CHECK OK|CHECK ERROR'} | Select-Object -Last 6)
  }
  $output=@{listener_exists=$true;single_item=$s.Contains('TT_ACTUALIDAD_MANUAL_EDITORIAL_V1');scoped_method=$s.Contains('function Build-EditorialMessage([string]$CommandId,$Control)');updater_tail=$rows}
  Write-Output ('TTRESULT:'+($output|ConvertTo-Json -Compress -Depth 4))
} catch { Write-Output ('TTRESULT:'+(@{error=$_.Exception.Message}|ConvertTo-Json -Compress)) }
